import AppKit
import Carbon

/// macOS has no "clipboard changed" event, so poll the change counter.
@MainActor
final class ClipboardWatcher {
    // Markers password managers and similar apps put on copies that should not
    // be recorded. See nspasteboard.org.
    private static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    /// What Holt puts on the clipboard.
    enum Content {
        case text(String)
        case image(Data, format: String, sourceApp: String?)
    }

    private let onText: (String, String?) -> Void
    private let onImage: (RawImage, String?) -> Void
    private let incoming: () -> Content?
    private var lastChange = NSPasteboard.general.changeCount
    private var timer: Timer?

    /// `incoming` returns a clip from another device to put on the clipboard.
    init(
        onText: @escaping (_ text: String, _ sourceApp: String?) -> Void,
        onImage: @escaping (_ image: RawImage, _ sourceApp: String?) -> Void,
        incoming: @escaping () -> Content?
    ) {
        self.onText = onText
        self.onImage = onImage
        self.incoming = incoming
    }

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: 0.5, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.check() }
        }
    }

    /// Puts a clip on the clipboard without recording it as a new copy.
    func put(_ content: Content) {
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        switch content {
        case .text(let text):
            pasteboard.setString(text, forType: .string)
        case .image(let bytes, let format, let sourceApp):
            pasteboard.writeObjects([Images.pasteboardItem(bytes: bytes, format: format, sourceApp: sourceApp)])
        }
        lastChange = pasteboard.changeCount
    }

    private func check() {
        if let content = incoming() {
            put(content)
            return
        }
        let pasteboard = NSPasteboard.general
        guard pasteboard.changeCount != lastChange else { return }
        lastChange = pasteboard.changeCount

        // Look at each item: `pasteboard.types` is the union over all of them.
        let items = pasteboard.pasteboardItems ?? []
        guard !items.contains(where: { item in item.types.contains { Self.ignoredTypes.contains($0.rawValue) } }) else { return }
        let app = NSWorkspace.shared.frontmostApplication?.bundleIdentifier
        // An image file copied in Finder is kept as the image, not its name.
        // Otherwise text wins when an item carries both, so Word copies stay text.
        if Prefs.recordImages, let file = items.lazy.compactMap(Images.file).first {
            onImage(file, app)
        } else if let text = items.lazy.compactMap({ $0.string(forType: .string) }).first {
            onText(text, app)
        } else if Prefs.recordImages, let image = items.lazy.compactMap(Images.raw).first {
            onImage(image, app)
        }
    }
}

/// Posts ⌘V to the frontmost app. Needs Accessibility access.
/// Uses the key position of V on a US layout, which is also right for AZERTY
/// and QWERTZ, but not for Dvorak. Look up the layout's V key if that comes up.
func sendPasteKeystroke() {
    let source = CGEventSource(stateID: .combinedSessionState)
    let v = CGKeyCode(kVK_ANSI_V)
    for keyDown in [true, false] {
        let event = CGEvent(keyboardEventSource: source, virtualKey: v, keyDown: keyDown)
        event?.flags = .maskCommand
        event?.post(tap: .cghidEventTap)
    }
}

/// One global shortcut through Carbon, which needs no permission.
final class HotKey {
    private static var action: (() -> Void)?
    private var ref: EventHotKeyRef?

    init(_ shortcut: Shortcut, action: @escaping () -> Void) {
        HotKey.action = action
        var spec = EventTypeSpec(eventClass: OSType(kEventClassKeyboard), eventKind: UInt32(kEventHotKeyPressed))
        InstallEventHandler(
            GetApplicationEventTarget(),
            { _, _, _ in
                HotKey.action?()
                return noErr
            }, 1, &spec, nil, nil)
        register(shortcut)
    }

    func register(_ shortcut: Shortcut) {
        if let ref { UnregisterEventHotKey(ref) }
        let id = EventHotKeyID(signature: OSType(0x484F_4C54), id: 1)  // "HOLT"
        RegisterEventHotKey(shortcut.keyCode, shortcut.modifiers, id, GetApplicationEventTarget(), 0, &ref)
    }
}
